//! Parser parity with Calliope's pyparsing grammar on every math string of the pre-defined
//! math, the math gallery and the example models, plus seeded mutants of each string.
//!
//! The fixture is generated by `tests/oracle/parse_oracle.py`: for each string it holds
//! the pyparsing parse tree `repr`, or that parsing failed.

use std::collections::{BTreeMap, BTreeSet};

use calliope_math::{Names, StringKind, parse};
use serde::Deserialize;

#[derive(Deserialize)]
struct Corpus {
    name_sets: BTreeMap<String, NameSet>,
    cases: Vec<Case>,
}

#[derive(Deserialize)]
struct NameSet {
    #[serde(rename = "where")]
    where_: WhereNames,
    expression: Vec<String>,
    postprocessed_where: Vec<String>,
    postprocessed_expression: Vec<String>,
}

#[derive(Deserialize)]
struct WhereNames {
    dimensions: Vec<String>,
    inputs: Vec<String>,
    results: Vec<String>,
}

#[derive(Deserialize)]
struct Case {
    set: String,
    path: String,
    context: String,
    string: String,
    ok: bool,
    #[serde(default)]
    repr: Option<String>,
}

fn set(v: &[String]) -> BTreeSet<String> {
    v.iter().cloned().collect()
}

/// Expression names are one flat set in Calliope; the roles only matter for typechecking,
/// so the corpus puts them all under `inputs`.
fn names_for(ns: &NameSet, context: &str) -> (StringKind, Names) {
    let pp = context.ends_with("_postprocessed");
    let base = context.trim_end_matches("_postprocessed");
    if base == "where" {
        let names = Names {
            dimensions: set(&ns.where_.dimensions),
            inputs: set(&ns.where_.inputs),
            results: set(&ns.where_.results),
            postprocessed: if pp {
                set(&ns.postprocessed_where)
            } else {
                BTreeSet::new()
            },
        };
        return (StringKind::Where, names);
    }
    let kind = match base {
        "equation" => StringKind::Equation,
        "arithmetic" => StringKind::Arithmetic,
        "sub_expression" => StringKind::SubExpression,
        "slice" => StringKind::Slice,
        other => panic!("unknown context {other}"),
    };
    let mut inputs = set(&ns.expression);
    if pp {
        inputs.extend(ns.postprocessed_expression.iter().cloned());
    }
    let names = Names {
        inputs,
        ..Names::default()
    };
    (kind, names)
}

#[test]
fn corpus_matches_pyparsing() {
    let text = include_str!("fixtures/parse_corpus.json");
    let corpus: Corpus = serde_json::from_str(text).unwrap();
    let mut failures = Vec::new();
    let mut n_ok = 0;
    for case in &corpus.cases {
        let ns = &corpus.name_sets[&case.set];
        let (kind, names) = names_for(ns, &case.context);
        let got = parse(kind, &case.string, &names);
        match (&got, case.ok) {
            (Ok(node), true) => {
                let expected = case.repr.as_deref().unwrap();
                if node.to_string() != expected {
                    failures.push(format!(
                        "{} [{}] {:?}\n  python: {expected}\n  rust:   {node}",
                        case.path, case.context, case.string
                    ));
                } else {
                    n_ok += 1;
                }
            }
            (Err(_), false) => n_ok += 1,
            (Ok(node), false) => failures.push(format!(
                "{} [{}] {:?}\n  python: parse error\n  rust:   {node}",
                case.path, case.context, case.string
            )),
            (Err(e), true) => failures.push(format!(
                "{} [{}] {:?}\n  python: {}\n  rust:   error {e} at {:?}",
                case.path,
                case.context,
                case.string,
                case.repr.as_deref().unwrap(),
                e.span
            )),
        }
    }
    assert!(
        failures.is_empty(),
        "{} of {} cases differ ({n_ok} agree):\n{}",
        failures.len(),
        corpus.cases.len(),
        failures.join("\n")
    );
}
